import { useState } from '@lynx-js/react';
import type { Pokemon } from '../shares/pokemon.model';
import { capitalize } from '../helpers/capitalize';

interface PokemonCardProps {
  pokemon: Pokemon;
  onClick: () => void;
  lazyLoad?: boolean;
}

export function PokemonCard({ pokemon, onClick, lazyLoad }: PokemonCardProps) {
  const [imageLoaded, setImageLoaded] = useState(false);

  return (
    <view className="Card" bindtap={onClick}>
      {!imageLoaded && (
        <view className="CardImagePlaceholder shimmer-effect">
          {/* Optional: Add a small loading spinner here if desired */}
        </view>
      )}
      <image
        src={pokemon.imageUrl}
        className="CardImage"
        lazy-load={lazyLoad || false}
        onLoad={() => setImageLoaded(true)}
        style={{ display: imageLoaded ? 'block' : 'none' }}
      />
      <view className="CardContent">
        <text className="CardId">#{pokemon.id.toString().padStart(3, '0')}</text>
        <text className="CardName">{capitalize(pokemon.name)}</text>
        <view className="TypeContainer">
          {pokemon.types.map(type => (
            <text key={type} className={`TypeBadge Type-${type}`}>{type.toUpperCase()}</text>
          ))}
        </view>
      </view>
    </view>
  );
}